   102  // Returns whether the class can handle the format of the given file.
   103  bool PLYImporter::CanRead(const std::string &pFile, IOSystem *pIOHandler, bool checkSig) const {
   104      const std::string extension = GetExtension(pFile);
   105
   106      if (extension == "ply") {
   107          return true;
   108      }
   109
   110      if (!extension.length() || checkSig) {
   111          if (!pIOHandler) {
   112              return true;
   113          }
   114          static const char *tokens[] = {
   115              "ply"
   116          };
   117          return SearchFileHeaderForToken(pIOHandler, pFile, tokens, 1);
   118      }
   119
   120      return false;
   121  }
