   129  static bool isBigEndian(const char *szMe) {
   130      ai_assert(nullptr != szMe);
   131
   132      // binary_little_endian
   133      // binary_big_endian
   134      bool isBigEndian(false);
   135  #if (defined AI_BUILD_BIG_ENDIAN)
   136      if ('l' == *szMe || 'L' == *szMe) {
   137          isBigEndian = true;
   138      }
   139  #else
   140      if ('b' == *szMe || 'B' == *szMe) {
   141          isBigEndian = true;
   142      }
   143  #endif // ! AI_BUILD_BIG_ENDIAN
   144
   145      return isBigEndian;
   146  }
