   148  // ------------------------------------------------------------------------------------------------
   149  // Imports the given file into the given scene structure.
   150  void PLYImporter::InternReadFile(const std::string &pFile, aiScene *pScene, IOSystem *pIOHandler) {
   151      const std::string mode = "rb";
   152      std::unique_ptr<IOStream> fileStream(pIOHandler->Open(pFile, mode));
   153      if (!fileStream.get()) {
   154          throw DeadlyImportError("Failed to open file ", pFile, ".");
   155      }
   156
   157      // Get the file-size
   158      const size_t fileSize(fileStream->FileSize());
   159      if (0 == fileSize) {
   160          throw DeadlyImportError("File ", pFile, " is empty.");
   161      }
   162
   163      IOStreamBuffer<char> streamedBuffer(1024 * 1024);
   164      streamedBuffer.open(fileStream.get());
   165
   166      // the beginning of the file must be PLY - magic, magic
   167      std::vector<char> headerCheck;
   168      streamedBuffer.getNextLine(headerCheck);
   169
   170      if ((headerCheck.size() < 3) ||
   171              (headerCheck[0] != 'P' && headerCheck[0] != 'p') ||
   172              (headerCheck[1] != 'L' && headerCheck[1] != 'l') ||
   173              (headerCheck[2] != 'Y' && headerCheck[2] != 'y')) {
   174          streamedBuffer.close();
   175          throw DeadlyImportError("Invalid .ply file: Incorrect magic number (expected 'ply' or 'PLY').");
   176      }
   177
   178      std::vector<char> mBuffer2;
   179      streamedBuffer.getNextLine(mBuffer2);
   180      mBuffer = (unsigned char *)&mBuffer2[0];
   181
   182      char *szMe = (char *)&this->mBuffer[0];
   183      SkipSpacesAndLineEnd(szMe, (const char **)&szMe);
   184
   185      // determine the format of the file data and construct the aiMesh
   186      PLY::DOM sPlyDom;
   187      this->pcDOM = &sPlyDom;
   188
   189      if (TokenMatch(szMe, "format", 6)) {
   190          if (TokenMatch(szMe, "ascii", 5)) {
   191              SkipLine(szMe, (const char **)&szMe);
   192              if (!PLY::DOM::ParseInstance(streamedBuffer, &sPlyDom, this)) {
   193                  if (mGeneratedMesh != nullptr) {
   194                      delete (mGeneratedMesh);
   195                      mGeneratedMesh = nullptr;
   196                  }
   197
   198                  streamedBuffer.close();
   199                  throw DeadlyImportError("Invalid .ply file: Unable to build DOM (#1)");
   200              }
   201          } else if (!::strncmp(szMe, "binary_", 7)) {
   202              szMe += 7;
   203              const bool bIsBE(isBigEndian(szMe));
   204
   205              // skip the line, parse the rest of the header and build the DOM
   206              if (!PLY::DOM::ParseInstanceBinary(streamedBuffer, &sPlyDom, this, bIsBE)) {
   207                  if (mGeneratedMesh != nullptr) {
   208                      delete (mGeneratedMesh);
   209                      mGeneratedMesh = nullptr;
   210                  }
   211
   212                  streamedBuffer.close();
   213                  throw DeadlyImportError("Invalid .ply file: Unable to build DOM (#2)");
   214              }
   215          } else {
   216              if (mGeneratedMesh != nullptr) {
   217                  delete (mGeneratedMesh);
   218                  mGeneratedMesh = nullptr;
   219              }
   220
   221              streamedBuffer.close();
   222              throw DeadlyImportError("Invalid .ply file: Unknown file format");
   223          }
   224      } else {
   225          AI_DEBUG_INVALIDATE_PTR(this->mBuffer);
   226          if (mGeneratedMesh != nullptr) {
   227              delete (mGeneratedMesh);
   228              mGeneratedMesh = nullptr;
   229          }
   230
   231          streamedBuffer.close();
   232          throw DeadlyImportError("Invalid .ply file: Missing format specification");
   233      }
   234
   235      //free the file buffer
   236      streamedBuffer.close();
   237
   238      if (mGeneratedMesh == nullptr) {
   239          throw DeadlyImportError("Invalid .ply file: Unable to extract mesh data ");
   240      }
   241
   242      // if no face list is existing we assume that the vertex
   243      // list is containing a list of points
   244      bool pointsOnly = mGeneratedMesh->mFaces == nullptr ? true : false;
   245      if (pointsOnly) {
   246          mGeneratedMesh->mPrimitiveTypes = aiPrimitiveType::aiPrimitiveType_POINT;
   247      }
   248
   249      // now load a list of all materials
   250      std::vector<aiMaterial *> avMaterials;
   251      std::string defaultTexture;
   252      LoadMaterial(&avMaterials, defaultTexture, pointsOnly);
   253
   254      // now generate the output scene object. Fill the material list
   255      pScene->mNumMaterials = (unsigned int)avMaterials.size();
   256      pScene->mMaterials = new aiMaterial *[pScene->mNumMaterials];
   257      for (unsigned int i = 0; i < pScene->mNumMaterials; ++i) {
   258          pScene->mMaterials[i] = avMaterials[i];
   259      }
   260
